int runFeatures421(){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;auto require=[](bool ok,const char* text){if(!ok)throw std::runtime_error(text);};try{auto root=LibraryStore::root();root.createDirectory();auto source=std::make_shared<AudioData>();source->rate=48000;source->buffer.setSize(1,48000);for(int n=0;n<48000;++n)source->buffer.setSample(0,n,.03f*std::sin(n*juce::MathConstants<double>::twoPi*220/48000));source->peakAmplitude=.03;source->path=root.getChildFile("Source A.wav").getFullPathName();require(writeRenderedAudio(juce::File(source->path),source->buffer,48000),"source fixture");auto soundB=root.getChildFile("Source B.wav");require(writeRenderedAudio(soundB,source->buffer,48000),"second fixture");
 Processor p(false);p.autoSave=false;p.audio=source;p.trimEnd=48000;p.sourceBpm=120;p.split(1);p.oneShotMode=p.multiMode=true;std::vector<SfzRegion> rows;for(int i=0;i<3;++i){SfzRegion r;r.source=source;r.root=i==1?64:60;r.start=i*12000;r.end=(i+1)*12000;r.loopStart=r.start;r.loopEnd=r.end;r.pitchMethod="Audio";r.roundRobinGroup=r.root+1;r.melodicSliceId=i+1;rows.push_back(r);}MultiMapping::autoMap(rows);p.multiMap=std::make_shared<const std::vector<SfzRegion>>(rows);p.sequence.notes={{1,60,100,1,0,.5,1},{2,64,100,1,.5,.5,2},{3,60,100,1,1,.5,3}};p.sequence.changed();p.resetHistory();MultiEditor multi(p,{},{});require(multi.delete421ForCheck(),"hover trash deletion");require(p.shotRegions().size()==2&&p.sequence.notes.size()==2&&p.audio==source,"delete map and linked note without touching source");require(juce::File(source->path).existsAsFile(),"original retained");require(p.undoRedo(false)&&p.shotRegions().size()==3&&p.sequence.notes.size()==3,"Undo restores region and trigger");
 for(auto& r:rows)r.melodicSliceId=0;p.multiMap=std::make_shared<const std::vector<SfzRegion>>(rows);for(auto& n:p.sequence.notes)n.sourceRegion=0;p.resetHistory();require(p.deleteMultiRegion(1)&&p.sequence.notes.size()==2,"legacy melodic links inferred");require(p.undoRedo(false)&&p.sequence.notes.size()==3,"legacy region Undo");
 p.multiMode=false;p.oneShotMode=true;p.sequence.notes={{1,60,80,1,0,1},{2,64,110,1,0,1},{3,67,100,1,2,.5}};p.sequence.nextId=4;p.sequence.changed();p.extractionActive=true;p.extractionOptions.monophonic=true;p.extractionSpectrogram=juce::Image(juce::Image::ARGB,8,128,true);p.resetHistory();SequencerEditor panel(p);panel.setSize(1040,720);require(panel.edit421ForCheck(),"mono deletion, pitch-label drag and Fold Notes");
 p.sequence.bars=1;p.sequence.notes={{1,60,100,1,0,.25},{2,72,100,1,4.1,.25},{3,74,100,1,6.3,.25}};p.sequence.changed();p.extractionOptions.monophonic=false;p.sequenceAutoQuantize=true;p.sequenceSwingGrid=.25;p.sequenceEnabled=true;p.swingEnabled=false;p.sequenceWasPlaying=false;auto display=p.sequenceForDisplay();require(display.notes[1].beat==4.1&&display.notes[2].beat==6.3,"quantise does not clamp outside notes");juce::MidiBuffer midi;int count=0;double step=120./60/48000;for(int frame=0;frame<288000;frame+=128){midi.clear();p.renderSequenceMidi(midi,frame*step,step,128,true);for(auto e:midi)if(e.getMessage().isNoteOn()){require(e.getMessage().getNoteNumber()==60,"out-of-range note fired at boundary");++count;}}require(count==3,"three loop cycles only contain in-range note");
 p.stretchMode=true;p.oneShotMode=false;p.extractionActive=true;p.sequenceEnabled=false;p.extractionMidiAudition=false;p.extractionInstrument=std::make_shared<Processor>(false);p.extractionInstrument->autoSave=false;p.extractionInstrumentPath="old-sound";p.sequenceAutoQuantize=false;p.extractionOptions.monophonic=false;require(panel.preview421ForCheck(juce::File(source->path),soundB),"browser preview, cancel and confirmation");
 RackProcessor rack;for(int i:{1,2}){auto& slot=*rack.loops[i];slot.audio=source;slot.oneShotMode=true;slot.normaliseEnabled=false;slot.shotRootNote=60;slot.shotEnvelope={0,0,1,.01f};}rack.prepareToPlay(48000,128);juce::AudioBuffer<float> output(2,128);midi.clear();midi.addEvent(juce::MidiMessage::noteOn(2,60,(juce::uint8)100),0);midi.addEvent(juce::MidiMessage::noteOn(3,60,(juce::uint8)100),0);rack.processBlock(output,midi);for(int i=0;i<25;++i){midi.clear();rack.processBlock(output,midi);}require(rack.level[1]>.001&&rack.level[2]>.001,"both sounding groups metered");RackEditor editor(rack);require(editor.meter421ForCheck(),"quiet group meters visible and peaks retained");std::cout<<"Hover trash + Undo, linked MIDI, non-resurrecting mono deletion, pitch-label drag, Fold Notes, loop bounds, preview confirmation and quiet meters passed\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4211;}}
